package com.aac.ieojwo.device.controller;
import com.aac.ieojwo.common.api.ApiResponse;import com.aac.ieojwo.device.domain.AacDevice;import com.aac.ieojwo.device.service.DeviceAuthService;import com.aac.ieojwo.location.service.LocationService;import com.aac.ieojwo.location.service.LocationService.*;import com.aac.ieojwo.report.service.SensorService;import com.aac.ieojwo.report.service.SensorService.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/device")
public class DeviceTelemetryController{private final DeviceAuthService auth;private final LocationService locations;private final SensorService sensors;public DeviceTelemetryController(DeviceAuthService a,LocationService l,SensorService s){auth=a;locations=l;sensors=s;}@PostMapping("/locations")public ApiResponse<LocationResponse> location(@RequestHeader(value="Authorization",required=false)String token,@RequestBody LocationRequest r){AacDevice d=auth.authenticate(token);return ApiResponse.ok(locations.record(d,r));}@PostMapping("/sensor-events")public ApiResponse<SensorResponse> sensor(@RequestHeader(value="Authorization",required=false)String token,@RequestBody SensorRequest r){return ApiResponse.ok(sensors.record(auth.authenticate(token),r));}@PostMapping("/emergency")public ApiResponse<Map<String,String>> emergency(@RequestHeader(value="Authorization",required=false)String token,@RequestBody(required=false)Map<String,String> body){sensors.emergency(auth.authenticate(token),body==null?null:body.get("message"));return ApiResponse.ok(Map.of("status","EMERGENCY"));}}
